// План specs/modals.md, 1.4 (кейс MD-04). Admin. Только чтение: перенос не выполняется («Transfer» не нажимается), окно закрывается Esc. @prod-safe
import { test, expect } from '@playwright/test';
import { ADMIN_STATE, DEVICES, closeWithEsc, expectOpaqueModalOverDimmedPage } from './modal-helpers';

test.use({ storageState: ADMIN_STATE });

test.describe('Модальные окна — непрозрачный фон (#08737d6c)', () => {
  for (const device of DEVICES) {
    test(`Transfer Inventory window is opaque over a dimmed page #08737d6c ${device} @prod-safe`, async ({ page }) => {
      // Шаг 1: Inventory → кнопка «Transfer Inventory» у первого товара
      await page.goto('/inventory');
      await page.getByTitle('Transfer Inventory').filter({ visible: true }).first().click();

      // Шаг 2: окно «Transfer Inventory» непрозрачное, страница затемнена
      const dialog = page.getByRole('dialog', { name: 'Transfer Inventory' });
      await expectOpaqueModalOverDimmedPage(page, dialog);
      await expect(dialog.getByText('From Location')).toBeVisible();

      // Шаг 3: Esc
      await closeWithEsc(page, dialog);
    });
  }
});
